def to_roman(n):
    val = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'),
        (1, 'I')
    ]
    res = ''
    for (v, r) in val:
        while n >= v:
            res += r
            n -= v
    return res

def from_roman(s):
    roman_dict = {
        'I': 1, 'IV': 4, 'V': 5, 'IX': 9,
        'X': 10, 'XL': 40, 'L': 50, 'XC': 90,
        'C': 100, 'CD': 400, 'D': 500, 'CM': 900,
        'M': 1000
    }
    total = 0
    i = 0
    while i < len(s):
        if i + 1 < len(s) and s[i:i+2] in roman_dict:
            total += roman_dict[s[i:i+2]]
            i += 2
        else:
            total += roman_dict[s[i]]
            i += 1
    return total

